def rle(s: str) -> str:
    if not s:
        return ""

    encoded = []
    count = 1
    current_char = s[0]

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            encoded.append(f"{current_char}{count}")
            current_char = s[i]
            count = 1

    encoded.append(f"{current_char}{count}")
    return "".join(encoded)
```

